package com.minion.core.tools.dev;
import com.google.gson.*;
import com.minion.core.tools.*;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.*;
import static org.junit.Assert.*;
public class OfficeArtifactVerificationTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();
 private static final String S="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
 private static final String R="http://schemas.openxmlformats.org/officeDocument/2006/relationships";
 private Path zip(String... entries)throws Exception {Path p=tmp.newFile(java.util.UUID.randomUUID().toString()+".zip").toPath();try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(p))){for(int i=0;i<entries.length;i+=2){z.putNextEntry(new ZipEntry(entries[i]));z.write(entries[i+1].getBytes(StandardCharsets.UTF_8));z.closeEntry();}}return p;}
 private JsonObject args(Path p,String action,String checks){JsonObject a=JsonParser.parseString("{action:'"+action+"',stableMs:100,officeChecks:"+checks+"}").getAsJsonObject();a.addProperty("path",p.toString());return a;}
 private ToolResult run(JsonObject a){return new ArtifactVerificationTool(new Workspace(tmp.getRoot().toString())).execute(a);}
 private Path doc()throws Exception{return zip("word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>合</w:t></w:r><w:r><w:t>同</w:t></w:r></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>金额</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:body></w:document>");}
 private Path book(String cells)throws Exception{return zip("xl/workbook.xml","<workbook xmlns='"+S+"' xmlns:r='"+R+"'><sheets><sheet name='表一' r:id='r1'/></sheets></workbook>","xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='r1' Type='"+R+"/worksheet' Target='worksheets/sheet1.xml'/></Relationships>","xl/worksheets/sheet1.xml","<worksheet xmlns='"+S+"'><sheetData><row>"+cells+"</row></sheetData></worksheet>");}
 @Test public void docTextAndPhysicalTableEntry()throws Exception{Path p=doc();ToolResult r=run(args(p,"docx","[{expectedText:'合同'},{table:0,row:0,column:0,expectedText:'金额'}]"));assertTrue(r.output,r.ok);assertTrue(r.output.contains(ArtifactVerifier.sha256(p)));assertTrue(r.output.contains("paginationVerified\":false"));assertFalse(run(args(p,"docx","[{table:0,row:0,column:0,expectedText:'错误'}]")).ok);}
 @Test public void formulaCacheIsNotRecalculation()throws Exception{Path p=book("<c r='A1'><f>1+1</f><v>2</v></c><c r='B1'><f>2+2</f></c><c r='C1' t='inlineStr'><is><t>你好</t></is></c>");ToolResult r=run(args(p,"xlsx","[{sheet:'表一',cell:'A1',expectedValue:'2',formulaCache:'present_unverified'},{sheet:'表一',cell:'B1',formulaCache:'missing'},{sheet:'表一',cell:'C1',expectedValue:'你好',formulaCache:'not_formula'}]"));assertTrue(r.output,r.ok);assertTrue(r.output.contains("recalculationVerified\":false"));assertFalse(run(args(p,"xlsx","[{sheet:'表一',cell:'A1',formulaCache:'missing'}]")).ok);assertFalse(run(args(p,"xlsx","[{sheet:'不存在',cell:'A1',expectedValue:'2'}]")).ok);assertFalse(run(args(p,"xlsx","[{sheet:'表一',cell:'D1',expectedValue:''}]")).ok);}
 @Test public void entryHashMismatchCannotBeOverridden()throws Exception{JsonObject a=args(doc(),"docx","[{expectedText:'合同'}]");a.addProperty("sha256",String.format("%064d",0));assertFalse(run(a).ok);}
 @Test public void schemaAndRiskWiring()throws Exception{ArtifactVerificationTool t=new ArtifactVerificationTool(new Workspace(tmp.getRoot().toString()));for(String action:new String[]{"docx","xlsx"}){assertTrue(ArtifactVerificationTool.readOnlyAction(action));JsonObject a=new JsonObject();a.addProperty("action",action);assertFalse(t.isHighRisk(a));}assertTrue(t.schema().getAsJsonObject("properties").has("officeChecks"));assertTrue(t.schema().getAsJsonObject("properties").has("screenshotPath"));JsonObject a=new JsonObject();a.addProperty("action","webpage");assertTrue(t.isHighRisk(a));}
 @Test public void emptyAssertionsAndOutOfRangeFail()throws Exception{Path p=doc();assertFalse(run(args(p,"docx","[]")).ok);assertFalse(run(args(p,"docx","[{table:8,row:0,column:0,expectedText:'a'}]")).ok);}
 @Test public void xxeAndTraversalRejected()throws Exception{Path p=zip("word/document.xml","<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><document>&e;</document>");assertFalse(run(args(p,"docx","[{expectedText:'a'}]")).ok);p=zip("../bad.xml","x");assertFalse(run(args(p,"docx","[{expectedText:'a'}]")).ok);}
 @Test public void zipBombBoundedByActualExpandedBytes()throws Exception{char[] chars=new char[4*1024*1024+1];java.util.Arrays.fill(chars,'x');Path p=zip("word/document.xml",new String(chars));ToolResult r=run(args(p,"docx","[{expectedText:'x'}]"));assertFalse(r.ok);assertTrue(r.output,r.output.contains("expanded size limit"));}
 @Test public void sharedStringsAndNonDefaultRelationship()throws Exception{Path p=zip("xl/workbook.xml","<workbook xmlns='"+S+"' xmlns:r='"+R+"'><sheets><sheet name='表一' r:id='r1'/></sheets></workbook>","xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='r1' Type='"+R+"/worksheet' Target='/xl/worksheets/custom.xml'/></Relationships>","xl/worksheets/custom.xml","<worksheet xmlns='"+S+"'><sheetData><row><c r='A1' t='s'><v>0</v></c></row></sheetData></worksheet>","xl/sharedStrings.xml","<sst xmlns='"+S+"'><si><r><t>合</t></r><r><t>同</t></r></si></sst>");ToolResult r=run(args(p,"xlsx","[{sheet:'表一',cell:'A1',expectedValue:'合同'}]"));assertTrue(r.output,r.ok);}
 @Test public void emptyStoredFormulaCacheIsStillPresent()throws Exception{Path p=book("<c r='A1' t='str'><f>IF(1,&quot;&quot;)</f><v></v></c>");ToolResult r=run(args(p,"xlsx","[{sheet:'表一',cell:'A1',expectedValue:'',formulaCache:'present_unverified'}]"));assertTrue(r.output,r.ok);}
 @Test public void externalRelationshipIsNeverFetched()throws Exception{Path p=zip("xl/workbook.xml","<workbook xmlns='"+S+"' xmlns:r='"+R+"'><sheets><sheet name='表一' r:id='r1'/></sheets></workbook>","xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='r1' Type='"+R+"/worksheet' TargetMode='External' Target='http://127.0.0.1:9/evil'/></Relationships>");ToolResult r=run(args(p,"xlsx","[{sheet:'表一',cell:'A1',expectedValue:'2'}]"));assertFalse(r.ok);assertTrue(r.output,r.output.contains("internal worksheet"));}}
